/**
 * Self-hosted display + mono faces, inlined as woff2 data URIs.
 *
 * The panel is a projector surface on venue wifi: a webfont that fails to load
 * silently rewrites the whole design. These four faces (Anybody variable 400-800,
 * Space Mono 400/700, latin subset) are embedded so the page renders identically
 * with the network unplugged. Regenerate from Google Fonts if the faces change.
 */
export const FONT_FACE_CSS = String.raw`
@font-face{font-family:'Anybody';font-style:normal;font-weight:400 800;font-display:swap;src:url(data:font/woff2;base64,) format('woff2');}
@font-face{font-family:'Space Mono';font-style:normal;font-weight:400;font-display:swap;src:url(data:font/woff2;base64,) format('woff2');}
@font-face{font-family:'Space Mono';font-style:normal;font-weight:700;font-display:swap;src:url(data:font/woff2;base64,) format('woff2');}
`;
